insert into study.questions (id, title, body, category_id, origin, source, choices, correct, explanation, asset_key, published) values
  ('DMQ-0196', '新工場の業務整理', '新工場の立上げにあたり、製品、調達、生産、出荷という業務領域にどのデータが属し、領域間で何を共有するかを一枚にまとめたい。列名やファイル配置は次の段階で決める。最も目的に合う資料はどれか。', 'DM-A-17-01-01', 'ai_original', 'AI生成オリジナル（IPA非公式）。出典：https://docs.google.com/document/d/1Ypv-RDymOhrlvk_lwFFaYgFYOdkMdHcOUDN7_KqExvY/edit', '[{"id":1,"body":"各表の列定義書","explanation":"列の型や桁数は表を実装するための情報で、業務領域間の全体像を示す単位としては細かすぎる。"},{"id":2,"body":"サブジェクトエリアモデル","explanation":"業務上の主題ごとにデータを大きくまとめ、その関係を示すので、各領域の境界と共有範囲を話し合える。"},{"id":3,"body":"夜間処理の運転時刻表","explanation":"処理の開始時刻や順序は分かるが、製品や出荷といった主題の関係は読み取れない。"},{"id":4,"body":"ディスクの配置図","explanation":"保管装置とファイルの対応が中心で、業務上の意味による区分を表さない。"}]'::jsonb, 2, '業務上の主題ごとにデータを大きくまとめ、その関係を示すので、各領域の境界と共有範囲を話し合える。', null, true),
  ('DMQ-0197', '温室の観測記録', '温室の端末は気温を記録する。集約装置は記録を受け取って時間帯別平均を作り、監視画面はその平均を取得する。この説明をデータフローとして正しく表したものはどれか。矢印はデータを渡す向きを示す。', 'DM-A-17-01-01', 'ai_original', 'AI生成オリジナル（IPA非公式）。出典：https://docs.google.com/document/d/1Ypv-RDymOhrlvk_lwFFaYgFYOdkMdHcOUDN7_KqExvY/edit', '[{"id":1,"body":"端末 → 監視画面（気温の記録）→ 集約装置（平均）","explanation":"画面が生の記録を受けて平均を渡す経路は記述されていない。"},{"id":2,"body":"集約装置 → 端末（気温の記録）→ 監視画面（平均）","explanation":"気温の発生元は端末であり、集約装置から端末に記録を送る関係ではない。"},{"id":3,"body":"監視画面 → 集約装置（平均）→ 端末（気温の記録）","explanation":"画面からの取得要求と、取得するデータそのものが流れる向きを混同している。"},{"id":4,"body":"端末 → 集約装置（気温の記録）→ 監視画面（平均）","explanation":"端末で生じた記録が集約装置で平均に加工され、その値を画面が受け取る。"}]'::jsonb, 4, '端末で生じた記録が集約装置で平均に加工され、その値を画面が受け取る。', null, true),
  ('DMQ-0198', '商品名の訂正', '店舗の販売端末は商品一覧のコピーを持つ。商品名は本部の台帳を正とし、端末へは毎晩、変更分を配信する。月曜の昼、本部で一つの商品名を訂正した。この構造から判断できることはどれか。', 'DM-A-17-01-01', 'ai_original', 'AI生成オリジナル（IPA非公式）。出典：https://docs.google.com/document/d/1Ypv-RDymOhrlvk_lwFFaYgFYOdkMdHcOUDN7_KqExvY/edit', '[{"id":1,"body":"次の配信を取り込むまでは、店舗に旧名が表示され得る。","explanation":"本部で訂正した時刻と、端末のコピーに反映する時刻が異なる。"},{"id":2,"body":"本部の台帳を訂正した瞬間に全端末で新名が表示される。","explanation":"夜間配信の構造には、昼の変更を即時に伝える経路が示されていない。"},{"id":3,"body":"店舗に旧名が表示されたなら、本部の訂正は失敗している。","explanation":"端末は自身のコピーを表示するので、端末の値だけでは本部の更新結果を判定できない。"},{"id":4,"body":"本部の台帳の訂正には、全端末で先に商品名を編集する必要がある。","explanation":"更新の起点は本部であり、店舗での先行編集を必要とする構造ではない。"}]'::jsonb, 1, '本部で訂正した時刻と、端末のコピーに反映する時刻が異なる。', null, true),
  ('DMQ-0199', '工房の講習申込み', '工房が講習会の受付を電子化する。データベース製品を選ぶ前に、担当者と概念データモデルの内容を合意したい。この段階で最も優先して確認する事項はどれか。', 'DM-A-17-02-01', 'ai_original', 'AI生成オリジナル（IPA非公式）。出典：https://docs.google.com/document/d/1Ypv-RDymOhrlvk_lwFFaYgFYOdkMdHcOUDN7_KqExvY/edit', '[{"id":1,"body":"申込番号に使用する整数型のバイト数","explanation":"型の格納サイズは実装時の判断であり、申込みが業務上何を意味するかを決めない。"},{"id":2,"body":"申込検索に使う索引の列順","explanation":"索引は検索の効率に関わる。まず、どの業務対象をどう結び付けるかを定める必要がある。"},{"id":3,"body":"同じ講習の別日程を、別の開催回として扱うか","explanation":"開催回と申込みが何を表し、どの単位で対応するかが決まるため、概念モデルの合意に必要である。"},{"id":4,"body":"申込表を格納するディスクの空き容量","explanation":"容量は保管設備の条件であり、講習と開催回との意味上の関係を決めない。"}]'::jsonb, 3, '開催回と申込みが何を表し、どの単位で対応するかが決まるため、概念モデルの合意に必要である。', null, true),
  ('DMQ-0200', '図書室の蔵書点検', '本には、同じ書名・版でも複数の現物がある。一冊ずつ異なる所蔵番号を貼り、破損状態を記録する。書名と版の情報は書誌番号で識別する。一冊だけが破損したとき、その一冊を正確に更新できる設計はどれか。', 'DM-A-17-02-01', 'ai_original', 'AI生成オリジナル（IPA非公式）。出典：https://docs.google.com/document/d/1Ypv-RDymOhrlvk_lwFFaYgFYOdkMdHcOUDN7_KqExvY/edit', '[{"id":1,"body":"書誌番号ごとに破損状態を一つ記録する。","explanation":"同じ書誌番号を持つ複数の現物のうち、どれが破損したかを区別できない。"},{"id":2,"body":"所蔵番号ごとに書誌番号と破損状態を記録する。","explanation":"破損が起こる単位は一冊の現物である。所蔵番号で対象を特定し、書誌番号から共通の書誌情報も参照できる。"},{"id":3,"body":"書名ごとに破損した冊数だけを記録する。","explanation":"冊数が分かっても、点検や修理の対象とする一冊を指定できない。"},{"id":4,"body":"版ごとに最後に点検した一冊の状態を上書きする。","explanation":"以前に点検した現物の状態が失われ、他の現物の状態と区別できない。"}]'::jsonb, 2, '破損が起こる単位は一冊の現物である。所蔵番号で対象を特定し、書誌番号から共通の書誌情報も参照できる。', null, true),
  ('DMQ-0201', '展示室の利用枠', '一つの利用枠には、予約がまだないか、予約が一件だけある。一件の予約は必ず一つの利用枠に対して行う。UMLの関連で、利用枠一つから見た予約の多重度と、予約一件から見た利用枠の多重度を、この順で表したものはどれか。', 'DM-A-17-02-02', 'ai_original', 'AI生成オリジナル（IPA非公式）。出典：https://docs.google.com/document/d/1Ypv-RDymOhrlvk_lwFFaYgFYOdkMdHcOUDN7_KqExvY/edit', '[{"id":1,"body":"0..1 と 1","explanation":"未予約なら予約数は0、埋まれば1である。成立した予約の行き先は必ず一枠である。"},{"id":2,"body":"1 と 0..1","explanation":"未予約の枠を認めず、逆に枠のない予約を認めてしまう。"},{"id":3,"body":"0..* と 1","explanation":"一枠に二件以上の予約を許してしまい、一枠一件までという条件に合わない。"},{"id":4,"body":"1 と 1","explanation":"全ての枠に予約を必須とするので、受付開始直後の空き枠を表現できない。"}]'::jsonb, 1, '未予約なら予約数は0、埋まれば1である。成立した予約の行き先は必ず一枠である。', null, true),
  ('DMQ-0202', '演奏会の担当表', '一つの楽曲を複数の奏者が演奏し、一人の奏者も複数の楽曲に出演する。同じ奏者は一つの楽曲で一つのパートを担当する。ある演奏会について、担当パートをどの単位で記録するのが適切か。', 'DM-A-17-02-02', 'ai_original', 'AI生成オリジナル（IPA非公式）。出典：https://docs.google.com/document/d/1Ypv-RDymOhrlvk_lwFFaYgFYOdkMdHcOUDN7_KqExvY/edit', '[{"id":1,"body":"奏者ごと","explanation":"同じ奏者でも楽曲により担当パートが異なり得る。"},{"id":2,"body":"楽曲ごと","explanation":"一つの楽曲に複数の奏者が参加するため、一つの値では各人の担当を表せない。"},{"id":3,"body":"演奏会ごと","explanation":"演奏会全体で一つの値を持っても、楽曲も奏者も区別できない。"},{"id":4,"body":"楽曲と奏者の組合せごと","explanation":"パートを一つに定める条件は、その演奏会で楽曲と奏者の両方を指定することである。"}]'::jsonb, 4, 'パートを一つに定める条件は、その演奏会で楽曲と奏者の両方を指定することである。', null, true),
  ('DMQ-0203', '修理伝票の行番号', '修理伝票には工場ごとの伝票番号を付ける。工場が違えば同じ伝票番号を使うことがある。各伝票の作業行には1から順に行番号を付ける。全工場の作業行を常に一意に識別するために必要な最小の組合せはどれか。', 'DM-A-17-02-01', 'ai_original', 'AI生成オリジナル（IPA非公式）。出典：https://docs.google.com/document/d/1Ypv-RDymOhrlvk_lwFFaYgFYOdkMdHcOUDN7_KqExvY/edit', '[{"id":1,"body":"伝票番号、行番号","explanation":"異なる工場の同番号の伝票では、同じ行番号が現れ得る。"},{"id":2,"body":"工場番号、行番号","explanation":"同じ工場でも、伝票が変われば行番号は1から始まる。"},{"id":3,"body":"工場番号、伝票番号、行番号","explanation":"前の二つで伝票が決まり、その中で行番号が作業行を決める。いずれかを省くと識別できない場合がある。"},{"id":4,"body":"工場番号、伝票番号","explanation":"伝票までは決まるが、その伝票にある複数の作業行を区別できない。"}]'::jsonb, 3, '前の二つで伝票が決まり、その中で行番号が作業行を決める。いずれかを省くと識別できない場合がある。', null, true),
  ('DMQ-0204', '保冷庫の点検記録', '保冷庫が8台ある。先月、3台は各2回、4台は各1回点検し、残る1台は点検しなかった。「点検記録」には点検1回につき1行を作り、対象の保冷庫1台を参照する。先月の点検記録の行数と、その記録が参照する異なる保冷庫の台数はどれか。', 'DM-A-17-02-01', 'ai_original', 'AI生成オリジナル（IPA非公式）。出典：https://docs.google.com/document/d/1Ypv-RDymOhrlvk_lwFFaYgFYOdkMdHcOUDN7_KqExvY/edit', '[{"id":1,"body":"8行、8台","explanation":"8は設備台帳の台数である。点検しなかった一台に点検記録は作られない。"},{"id":2,"body":"10行、7台","explanation":"行数は3×2＋4×1＝10。点検を受けた異なる保冷庫は3＋4＝7台である。"},{"id":3,"body":"7行、10台","explanation":"7は点検を受けた台数、10は点検の回数であり、二つの単位を逆にしている。"},{"id":4,"body":"10行、8台","explanation":"行数は正しいが、未点検の一台は先月の点検記録から参照されない。"}]'::jsonb, 2, '行数は3×2＋4×1＝10。点検を受けた異なる保冷庫は3＋4＝7台である。', null, true),
  ('DMQ-0205', '展示作品の貸出履歴', '美術館で、一つの作品を時期を変えて同じ施設へ何度も貸し出す。貸出のたびに全館で一意の貸出番号を付ける。返却後も、どの施設にいつ貸したかを一件ずつ調べたい。要件を満たす論理モデルはどれか。', 'DM-A-17-02-01', 'ai_original', 'AI生成オリジナル（IPA非公式）。出典：https://docs.google.com/document/d/1Ypv-RDymOhrlvk_lwFFaYgFYOdkMdHcOUDN7_KqExvY/edit', '[{"id":1,"body":"貸出番号をキーとする表に、作品番号、施設番号、貸出日、返却日を記録する。","explanation":"貸出という出来事に一行を割り当てる。同じ作品と施設でも、異なる貸出番号で複数回の記録を持てる。"},{"id":2,"body":"作品番号をキーとする作品表に、直近の施設番号と貸出日を上書きする。","explanation":"作品ごとの最新の行き先は分かるが、次の貸出時に過去の記録が失われる。"},{"id":3,"body":"施設番号をキーとする施設表に、直近の作品番号と返却日を上書きする。","explanation":"同じ施設が借りた別作品や過去の貸出を独立した記録として保持できない。"},{"id":4,"body":"作品番号と施設番号を組み合わせたキーの表に、貸出日を一つ記録する。","explanation":"同じ組合せの二回目の貸出を別の行として登録できず、反復する貸出を識別できない。"}]'::jsonb, 1, '貸出という出来事に一行を割り当てる。同じ作品と施設でも、異なる貸出番号で複数回の記録を持てる。', null, true)
